const names = $('Configure Inputs').first().json.usernames.split(',').map((name) => name.trim().replace(/^@/, '')).filter(Boolean);
if (names.length !== 2 || names[0] === names[1]) throw new Error('Provide two different public Instagram usernames, separated by a comma.');
return names.map((username) => ({ json: { username } }));

const results = $input.all().map((item) => item.json);
if (results.length !== 2 || results.some((result) => result.status !== 'succeeded' || !result.data)) throw new Error('Both public Instagram profiles must return data.');
const profiles = results.map((result) => { const d = result.data; return { username: d.username, name: d.full_name, biography: d.biography, followers: d.follower_count, following: d.following_count, category: d.category, is_private: d.is_private }; });
return [{ json: { source: 'Instagram public profile lookup', source_count: profiles.length, request_ids: results.map((result) => result.request_id), prompt: JSON.stringify({ profiles }) } }];

const answer = $input.first().json.choices?.[0]?.message?.content;
if (!answer) throw new Error('The text model returned no message content.');
const evidence = $('Prepare Evidence').first().json;
return [{ json: { summary: answer, source: evidence.source, source_count: evidence.source_count, request_ids: evidence.request_ids } }];
